"""Deterministic human report, independently regenerated by the verifier."""
import json


def render_result(config, metrics, records):
    rt = metrics['runtime_gate']
    lines = [f"Время: прогноз {rt['expected_seconds']:.6g} с; внутренний факт {rt['actual_seconds']:.6g} с; статус {rt['status']}.",
             'Полное время процесса, включая окончательную запись/повторную проверку, проверяется по run.json.',
             '', '# E002e CORR v001', '', 'Режим: '+config['mode']+'. Никакой автоматической научной приёмки.',
             'Источник: '+config['source_commit']+'.',
             'План/факт: '+json.dumps(rt['expected_counts'])+' / '+json.dumps(metrics['actual_counts'])+'.', '',
             '| Модель | Среднее абсолютное относительное отклонение потока | Вердикт |', '|---|---:|---|']
    for r in sorted(records, key=lambda r:r['case']['model']):
        v = r['result'].get('primary')
        lines.append(f"|{r['case']['model']}|{v['value'] if v else '—'}|{v['status'] if v else 'CALIBRATION_SHAM_ONLY'}|")
    lines += ['', 'Primary интегрирует модуль: затухающий осцилляторный транзиент тоже считается эффектом.',
              'Signed area и условные токи — диагностические показатели, не самостоятельные критерии механизма.',
              'NOT_REJECTED означает отсутствие превышения порога в данном окне/разрешении, не доказательство общей достаточности.',
              'Ненулевой эффект относится ко всем межподсистемным корреляциям, включая классические.',
              'Локальные состояния сохранены только в начальный момент. Энергия взаимодействия может изменяться.',
              'Сравнения между моделями вторичные: исходные возмущения и генераторы различаются.',
              'Хвост за H не оценён. Время восстановления, Фано и автопоэзис не назначаются.',
              'Численные интервалы инженерные, не строгие границы и не статистические сигмы.',
              'На ВМ сохранены начальные состояния и последний checkpoint каждого прогона; resume не реализован.',
              'Корневой manifest.json закрепляется внешним манифестом службы публикации и Git commit.']
    return '\n'.join(lines)+'\n'
